use std::io::{Read, IsTerminal};

fn main() {
    let matches = clap::Command::new("hx")
        .version("0.7.0")
        .about("Futuristic take on hexdump, made in Rust.\n")
        .arg(
            clap::Arg::new("cols")
                .short('c')
                .long("cols")
                .value_name("columns")
                .help("Set column length"),
        )
        .arg(
            clap::Arg::new("len")
                .short('l')
                .long("len")
                .value_name("len")
                .help("Set <len> bytes to read"),
        )
        .arg(
            clap::Arg::new("format")
                .short('f')
                .long("format")
                .value_name("format")
                .help("Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)")
                .value_parser(["o", "x", "X", "b"]),
        )
        .arg(
            clap::Arg::new("color")
                .short('t')
                .long("color")
                .value_name("color")
                .help("Set color tint terminal output. 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
        .arg(
            clap::Arg::new("array")
                .short('a')
                .long("array")
                .value_name("array_format")
                .help("Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)")
                .value_parser(["r", "c", "g", "p", "k", "j", "s", "f"]),
        )
        .arg(
            clap::Arg::new("func")
                .short('u')
                .long("func")
                .value_name("func_length")
                .help("Set function wave length"),
        )
        .arg(
            clap::Arg::new("places")
                .short('p')
                .long("places")
                .value_name("func_places")
                .help("Set function wave output decimal places"),
        )
        .arg(
            clap::Arg::new("prefix")
                .short('r')
                .long("prefix")
                .value_name("prefix")
                .help("Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
        .arg(
            clap::Arg::new("INPUTFILE")
                .help("Pass file path as an argument, or input data may be passed via stdin"),
        )
        .get_matches();

    // func mode takes precedence
    if matches.contains_id("func") && matches.get_one::<String>("func").is_some() {
        // validate places first (if present)
        let places: u64 = if let Some(p_str) = matches.get_one::<String>("places") {
            match p_str.parse::<u64>() {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("-p, --places <integer> expected. {:?}\nerror: {}", e, e);
                    std::process::exit(1);
                }
            }
        } else {
            4
        };
        let func_str = matches.get_one::<String>("func").unwrap();
        let func_len: u64 = match func_str.parse::<u64>() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("-u, --func <integer> expected. {:?}\nerror: {}", e, e);
                std::process::exit(1);
            }
        };
        do_func(func_len, places);
        return;
    }

    // non-func: open file first (if present) before validating cols/len
    let input_path: Option<String> = matches.get_one::<String>("INPUTFILE").cloned();
    let mut file_opt: Option<std::fs::File> = None;
    if let Some(ref path) = input_path {
        match std::fs::File::open(path) {
            Ok(f) => file_opt = Some(f),
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    }

    // validate cols
    let cols: u64 = if let Some(c_str) = matches.get_one::<String>("cols") {
        match c_str.parse::<u64>() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("-c, --cols <integer> expected. {:?}\nerror: {}", e, e);
                std::process::exit(1);
            }
        }
    } else {
        10
    };

    // validate len
    let len_limit: u64 = if let Some(l_str) = matches.get_one::<String>("len") {
        match l_str.parse::<u64>() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("-l, --len <integer> expected. {:?}\nerror: {}", e, e);
                std::process::exit(1);
            }
        }
    } else {
        0
    };

    // read data
    let mut data: Vec<u8> = Vec::new();
    if let Some(mut f) = file_opt {
        let res = if len_limit == 0 {
            f.read_to_end(&mut data)
        } else {
            // use take to limit
            let mut limited = f.take(len_limit);
            limited.read_to_end(&mut data)
        };
        if let Err(e) = res {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    } else {
        let stdin = std::io::stdin();
        let mut handle = stdin.lock();
        let res = if len_limit == 0 {
            handle.read_to_end(&mut data)
        } else {
            let mut limited = handle.take(len_limit);
            limited.read_to_end(&mut data)
        };
        if let Err(e) = res {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }

    // array mode?
    if let Some(array_fmt) = matches.get_one::<String>("array") {
        do_array(array_fmt, &data, cols);
        return;
    }

    // hex mode
    let format_opt: String = matches
        .get_one::<String>("format")
        .cloned()
        .unwrap_or_else(|| "x".to_string());
    let prefix_opt: String = matches
